import { HeaderComponent } from './header.component';
const navItems = [
    { label: 'Home', href: '/', active: true },
    { label: 'Products', href: '/products' },
    { label: 'Pricing', href: '/pricing' },
    { label: 'Docs', href: '/docs' },
];
const meta = {
    title: 'Components/Header',
    component: HeaderComponent,
    tags: ['autodocs'],
    parameters: {
        layout: 'fullscreen',
    },
    argTypes: {
        brandName: { control: 'text' },
        logoHref: { control: 'text' },
        ctaLabel: { control: 'text' },
        ctaHref: { control: 'text' },
    },
};
export default meta;
export const Default = {
    args: {
        brandName: 'Blueprint',
        navItems,
        ctaLabel: 'Get started',
        ctaHref: '/signup',
    },
};
export const LogoOnly = {
    args: { brandName: 'Blueprint' },
};
export const WithNavNoAction = {
    args: { brandName: 'Blueprint', navItems },
};
export const MinimalBrand = {
    args: { brandName: 'Acme Corp', ctaLabel: 'Sign in', ctaHref: '/login' },
};
